questionvariables.text:
/* 1. Randomize side length s */
s: 6 + rand(10); 

/* 2. Calculate a realistic apothem a */
a_exact: float(s / (2 * tan(%pi/7)));
a: decimalplaces(a_exact,2);

/* 3. Calculations */
ta_step: s * a;
ta: decimalplaces((7/2) * s * a, 2);

/* Common Mistakes for PRT */
m1: decimalplaces(7 * s * a, 2);     /* Forgot 1/2 */
m2: decimalplaces((1/2) * s * a, 2); /* Forgot 7 */
m3: 7 * s;                           /* Perimeter */
